<script setup lang="ts">
import { formatCreatedAt } from '~/utils/material'
import { exactBytes } from '~/utils/restore'
const work = useRestore()
const { connection, source, page, loading, listFailure, selected, preview, result, busy, failure, notice, pending, recovery, outdated, resultPast, canConfirm, canRetry, canReview, malformedPending, importDescriptor, imported, importing, hashing, importFailure, uploadFile } = work
const previewHeading = ref<HTMLElement | null>(null), resultHeading = ref<HTMLElement | null>(null)
async function showPreview(review = false) { if (await work.showPreview(review) || preview.value) { await nextTick(); previewHeading.value?.focus() } }
async function confirm() { if (await work.confirm()) { await nextTick(); resultHeading.value?.focus() } }
function choosePrevious() { const target = result.value?.previous_target; if (target) { work.startAnother(); work.choose(target) } }
function pick(event: Event) { const input = event.target as HTMLInputElement; void work.selectFile(input.files?.[0] ?? null); input.value = '' }
useHead({ title: '자료 복원 | 순창한상' })
</script>
<template>
  <div class="page-heading"><div><h1>자료 복원</h1><p>보존한 시점의 전체 자료를 확인하고 복원합니다.</p></div><NuxtLink class="back-link" to="/overview">작업 시작으로</NuxtLink></div>
  <p class="restore-intro">복원 전 자료와 기존 변경 기록·사진은 그대로 보관합니다. 복원 뒤 열려 있던 입력과 요청은 현재 자료와 다시 비교해야 합니다.</p>
  <div v-if="notice" class="notice" role="status">{{ notice }}</div><p v-if="failure" class="notice warning" role="alert">{{ failure }}</p><p v-if="malformedPending" class="notice warning" role="alert">보관된 복원 요청을 읽을 수 없어 새 복원을 보내지 않습니다. 아래 보존한 원입력을 확인해 주세요.</p>
  <section v-if="pending" class="restore-pending" aria-label="응답 미확인 복원 요청"><h2>원요청을 보존하고 있습니다</h2><p>대상과 요청을 바꾸지 않습니다. 완료를 확인하지 못했다면 같은 요청으로 결과를 확인하세요.</p><button v-if="canRetry" class="primary-button" type="button" :disabled="busy || connection !== 'connected'" @click="confirm">{{ busy ? '결과 확인 중…' : '같은 요청으로 결과 확인' }}</button><button v-if="canReview" class="primary-button" type="button" :disabled="busy || connection !== 'connected'" @click="showPreview(true)">현재 자료로 영향 다시 검토</button><button v-if="recovery === 'blocked'" class="text-button" type="button" :disabled="busy" @click="work.startAnother">원요청을 보관하고 새 복원 검토</button></section>
  <section v-if="result" class="restore-result" aria-labelledby="restore-result-title"><h2 id="restore-result-title" ref="resultHeading" tabindex="-1">{{ resultPast ? '이전에 완료한 복원 기록' : '전체 상태 복원 완료' }}</h2><p>{{ formatCreatedAt(result.recorded_at) }}에 완료했습니다. {{ resultPast ? '이후 다른 복원이 이루어졌으므로 현재 상태와 다릅니다.' : '새 자료 기준에서 입력을 이어갈 수 있습니다.' }}</p><NuxtLink class="primary-link" to="/overview">현재 자료 확인</NuxtLink><h3>복원 직전 상태도 보관했습니다</h3><p>{{ formatCreatedAt(result.previous_target.recorded_at) }} · 기록 {{ result.previous_target.sequence }}</p><button class="text-button" type="button" :disabled="busy" @click="choosePrevious">복원 직전 상태의 영향 검토하기</button><button class="text-button" type="button" :disabled="busy" @click="work.startAnother">다른 복원 지점 선택</button></section>
  <div class="restore-layout"><section aria-labelledby="restore-targets-title"><div class="profile-heading"><h2 id="restore-targets-title">복원 지점 선택</h2><button class="text-button" type="button" :disabled="loading || connection !== 'connected'" @click="work.load()">처음부터 다시 조회</button></div><label for="restore-source">지점 종류</label><select id="restore-source" v-model="source"><option value="journal">이 PC의 변경 기록</option><option value="import">가져온 JSON</option></select><p v-if="listFailure" class="notice warning" role="alert">{{ listFailure }} 이전 목록은 그대로 표시합니다.</p><p v-if="loading" role="status">복원 지점을 불러오는 중…</p><p v-if="page && !page.rows.length && !loading" class="empty-state">표시할 복원 지점이 없습니다.</p><ol v-if="page" class="restore-target-list"><li v-for="target in page.rows" :key="target.target_id"><button type="button" :data-restore-target="target.target_id" :aria-pressed="selected?.target_id === target.target_id" :disabled="busy || !!pending || malformedPending" @click="work.choose(target)"><strong>{{ formatCreatedAt(target.recorded_at) }}</strong><span>{{ target.source_kind === 'before_restore' ? '복원 직전 상태' : '변경 기록' }} · 기록 {{ target.sequence }}</span><span>{{ exactBytes(target.byte_length) }}</span></button></li></ol><button v-if="page?.next_cursor" class="text-button" type="button" :disabled="loading || connection !== 'connected'" @click="work.load(page.next_cursor!)">다음 복원 지점 25개 보기</button><p class="field-hint">한 번에 최대 25개씩 표시합니다. 새로 생긴 지점은 처음부터 다시 조회해 주세요.</p></section>
    <section aria-labelledby="restore-import-title"><h2 id="restore-import-title">JSON 가져오기</h2><p>앱이 보존한 JSON 파일 하나를 원문 그대로 가져옵니다. 가져오기만으로 현재 자료가 바뀌지는 않습니다.</p><label for="restore-file">복원 JSON 파일 · 최대 64 MiB</label><input id="restore-file" type="file" accept=".json,application/json" :disabled="importing || hashing" @change="pick"><p v-if="hashing" role="status">파일 내용을 확인하고 있습니다.</p><p v-if="importDescriptor">{{ importDescriptor.name }} · {{ exactBytes(String(importDescriptor.size)) }}<span v-if="!uploadFile"> · 같은 파일을 다시 선택해야 결과를 확인할 수 있습니다.</span></p><p v-if="importFailure" class="notice warning" role="alert">{{ importFailure }}</p><button class="secondary-link" type="button" :disabled="!uploadFile || importing || hashing || connection !== 'connected'" @click="work.importJson">{{ importing ? '가져오는 중…' : 'JSON 원문 가져오기' }}</button><button v-if="importDescriptor" class="text-button" type="button" :disabled="importing || hashing" @click="work.changeFile">원파일 확인 정보를 보관하고 다른 파일 선택</button><p v-if="imported" class="notice" role="status">JSON을 보관했습니다. 아래에서 전체 영향을 미리보기해 주세요.</p><p class="field-hint">JSON에 필요한 사진 파일도 이 PC의 자료 폴더에 있어야 합니다. 누락 여부는 미리보기에서 확인합니다.</p></section></div>
  <section v-if="selected && !result" class="restore-selection" aria-labelledby="restore-selected-title"><h2 id="restore-selected-title" ref="previewHeading" tabindex="-1">선택한 복원 지점</h2><p>{{ selected.target_id.startsWith('journal:') ? `변경 기록 ${selected.target_id.slice(8)}` : '가져온 JSON' }}</p><p class="field-hint material-id">내용 확인값 {{ selected.expected_sha256 }}</p><button class="primary-button" type="button" :disabled="busy || !!pending || connection !== 'connected'" @click="showPreview()">{{ busy ? '확인 중…' : '전체 영향 미리보기' }}</button><template v-if="preview"><p v-if="outdated" class="notice warning" role="status">미리보기 뒤 자료가 변경되었습니다. 전체 영향을 다시 확인해 주세요.</p><RestoreComparison :value="preview"/><p class="restore-confirm-note">확정하면 현재 사용하는 전체 상태가 이 미리보기의 복원 후 상태로 바뀝니다.</p><button class="primary-button" type="button" :disabled="!canConfirm" @click="confirm">선택한 전체 상태로 복원 확정</button></template></section>
  <RetainedInputs />
</template>
